-- Generated by NASAQ Settings — do not edit by hand.
-- App Switcher (nasaq.switcher): ALT + TAB with previews. When the switcher is
-- turned off in NASAQ Settings it falls back to Omarchy's cycle-and-raise.
hl.unbind("ALT + TAB")
hl.unbind("ALT + SHIFT + TAB")
o.bind("ALT + TAB", "App switcher: next", "omarchy-shell -q nasaq.switcher next")
o.bind("ALT + SHIFT + TAB", "App switcher: previous", "omarchy-shell -q nasaq.switcher prev")
-- Releasing Alt confirms the choice, even on a very quick tap (the overlay may
-- not have the keyboard yet). A no-op when the switcher is closed.
o.bind("ALT + Alt_L", nil, "omarchy-shell -q nasaq.switcher confirm", { release = true })
o.bind("ALT + Alt_R", nil, "omarchy-shell -q nasaq.switcher confirm", { release = true })
